const CORS_HEADERS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'content-type, accept, authorization, mcp-session-id, mcp-protocol-version',
  'Access-Control-Expose-Headers': 'mcp-session-id',
};

const TOOL_NAME = 'get_weather';

const TOOLS = [
  {
    name: TOOL_NAME,
    description: 'Get the current temperature and wind speed plus the hourly forecast for a location.',
    inputSchema: {
      type: 'object',
      properties: {
        latitude: { type: 'number', description: 'Latitude in decimal degrees.' },
        longitude: { type: 'number', description: 'Longitude in decimal degrees.' },
      },
      required: ['latitude', 'longitude'],
    },
  },
];

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json',
      ...CORS_HEADERS,
    },
  });
}

function empty(status: number): Response {
  return new Response(null, {
    status,
    headers: { ...CORS_HEADERS },
  });
}

function rpcResult(id: unknown, result: unknown) {
  return { jsonrpc: '2.0', id, result };
}

function rpcError(id: unknown, code: number, message: string, data?: unknown) {
  const error: any = { code, message };
  if (data !== undefined) error.data = data;
  return { jsonrpc: '2.0', id, error };
}

async function getWeather(latitude: number, longitude: number): Promise<string> {
  const url = new URL('https://api.open-meteo.com/v1/forecast');
  url.searchParams.set('latitude', String(latitude));
  url.searchParams.set('longitude', String(longitude));
  url.searchParams.set('current', 'temperature_2m,wind_speed_10m');
  url.searchParams.set('hourly', 'temperature_2m,relative_humidity_2m,wind_speed_10m');
  const res = await fetch(url.toString());
  if (!res.ok) {
    throw new Error(`Open-Meteo request failed: ${res.status}`);
  }
  return await res.text();
}

export default {
  async fetch(request: Request): Promise<Response> {
    const method = request.method.toUpperCase();

    if (method === 'OPTIONS') {
      return new Response(null, {
        status: 204,
        headers: { ...CORS_HEADERS },
      });
    }

    if (method === 'GET' || method === 'DELETE') {
      return empty(405);
    }

    if (method !== 'POST') {
      return json(rpcError(null, -32600, 'Method not allowed'), 405); // Hmm, spec says unknown method as JSON-RPC error never 4xx, but that's for JSON-RPC methods, not HTTP methods. For other HTTP methods, 405 is fine.
    }

    let body: any;
    try {
      body = await request.json();
    } catch {
      return json(rpcError(null, -32700, 'Parse error'), 200);
    }

    // Notification: no id
    if (body && typeof body === 'object' && !('id' in body)) {
      return new Response(null, { status: 202, headers: { ...CORS_HEADERS } });
    }

    const id = body?.id ?? null;
    const rpcMethod = body?.method;

    if (rpcMethod === 'initialize') {
      const protocolVersion = body?.params?.protocolVersion;
      const result = {
        protocolVersion,
        capabilities: { tools: {} },
        serverInfo: { name: 'weather-mcp', version: '1.0.0' },
      };
      return json(rpcResult(id, result), 200);
    }

    if (rpcMethod === 'tools/list') {
      return json(rpcResult(id, { tools: TOOLS }), 200);
    }

    if (rpcMethod === 'tools/call') {
      const name = body?.params?.name;
      const args = body?.params?.arguments ?? {};
      if (name !== TOOL_NAME) {
        return json(rpcError(id, -32602, `Unknown tool: ${name}`), 200);
      }
      const lat = Number(args.latitude);
      const lon = Number(args.longitude);
      if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
        return json(rpcError(id, -32602, 'Invalid arguments: latitude and longitude must be numbers'), 200);
      }
      try {
        const text = await getWeather(lat, lon);
        return json(rpcResult(id, { content: [{ type: 'text', text }] }), 200);
      } catch (e) {
        return json(rpcError(id, -32603, `Internal error: ${(e as Error).message}`), 200);
      }
    }

    // Unknown JSON-RPC method -> error at 200
    return json(rpcError(id, -32601, `Method not found: ${rpcMethod}`), 200);
  },
};
